     1  import {useCardAnimation} from '@react-navigation/stack';
     2  import React from 'react';
     3  import {Animated, View} from 'react-native';
     4  import PressableWithoutFeedback from '@components/Pressable/PressableWithoutFeedback';
     5  import useLocalize from '@hooks/useLocalize';
     6  import useThemeStyles from '@hooks/useThemeStyles';
     7  import CONST from '@src/CONST';
     8
     9  type BaseOverlayProps = {
    10      /* Whether to use native styles tailored for native devices */
    11      shouldUseNativeStyles: boolean;
    12
    13      /* Callback to close the modal */
    14      onPress?: () => void;
    15
    16      /* Returns whether a modal is displayed on the left side of the screen. By default, the modal is displayed on the right */
    17      isModalOnTheLeft?: boolean;
    18  };
    19
    20  function BaseOverlay({shouldUseNativeStyles, onPress, isModalOnTheLeft = false}: BaseOverlayProps) {
    21      const styles = useThemeStyles();
    22      const {current} = useCardAnimation();
    23      const {translate} = useLocalize();
    24
    25      return (
    26          <Animated.View
    27              id="BaseOverlay"
    28              style={shouldUseNativeStyles ? styles.nativeOverlayStyles(current) : styles.overlayStyles(current, isModalOnTheLeft)}
    29          >
    30              <View style={[styles.flex1, styles.flexColumn]}>
    31                  {/* In the latest Electron version buttons can't be both clickable and draggable.
    32               That's why we added this workaround. Because of two Pressable components on the desktop app
    33               we have 30px draggable ba at the top and the rest of the dimmed area is clickable. On other devices,
    34               everything behaves normally like one big pressable */}
    35                  <PressableWithoutFeedback
    36                      style={[styles.draggableTopBar, styles.boxShadowNone]}
    37                      onPress={onPress}
    38                      accessibilityLabel={translate('common.close')}
    39                      role={CONST.ROLE.BUTTON}
    40                      id={CONST.OVERLAY.TOP_BUTTON_NATIVE_ID}
    41                      tabIndex={-1}
    42                  />
    43                  <PressableWithoutFeedback
    44                      style={[styles.flex1, styles.boxShadowNone]}
    45                      onPress={onPress}
    46                      accessibilityLabel={translate('common.close')}
    47                      role={CONST.ROLE.BUTTON}
    48                      noDragArea
    49                      id={CONST.OVERLAY.BOTTOM_BUTTON_NATIVE_ID}
    50                      tabIndex={-1}
    51                  />
    52              </View>
    53          </Animated.View>
    54      );
    55  }
    56
    57  BaseOverlay.displayName = 'BaseOverlay';
    58
    59  export type {BaseOverlayProps};
    60  export default BaseOverlay;

